INSERT INTO Pve_Info (ID, Name, Type, LevelLimits, SimpleTemplateIds, NormalTemplateIds, HardTemplateIds, TerrorTemplateIds, EpicTemplateIds, NightmareTemplateIds, Pic, Description, Ordering, AdviceTips, BossFightNeedMoney, MinLv, MaxLv, FightPower, Missions) VALUES (23, N'Rừng Ma Pháp', 21, 30, N'40002,40001', N'40002,40001', N'40002,40001', N'40002,40001', N'', N'', N'', N'Một tiếng thét vọng ra từ khu rừng đó, khu rừng bị ma pháp bao trùm, bị nguyền rủa hay có sức mạnh to lớn? Không ai biết! Cần nhờ đến các dũng sĩ đi tìm câu trả lời...', 8, N'30-44|45-54|55-64|65-70', N'', 30, 70, N'350K|450K|800K|2500K|0|0', N'');
INSERT INTO Pve_Info (ID, Name, Type, LevelLimits, SimpleTemplateIds, NormalTemplateIds, HardTemplateIds, TerrorTemplateIds, EpicTemplateIds, NightmareTemplateIds, Pic, Description, Ordering, AdviceTips, BossFightNeedMoney, MinLv, MaxLv, FightPower, Missions) VALUES (24, N'Ảo Ảnh Đồi Cát ', 21, 30, N'11162,-100', 11162, 11162, 11162, N'', N'', N'', N'Một đồi cát đã từng rất phồn hoa, những dũng sĩ vào đồi cát này chỉ thấy ảo ảnh của sự đói khát, đau khổ, tuyệt vọng. Thoát ra được hay không đều dựa vào ý chí bản thân!', 9, N'30-44|45-54|55-64|65-70', N'', 30, 70, N'350K|450K|800K|2500K|0|0', N'');
INSERT INTO Pve_Info (ID, Name, Type, LevelLimits, SimpleTemplateIds, NormalTemplateIds, HardTemplateIds, TerrorTemplateIds, EpicTemplateIds, NightmareTemplateIds, Pic, Description, Ordering, AdviceTips, BossFightNeedMoney, MinLv, MaxLv, FightPower, Missions) VALUES (29, N'Trang Viên Đỏ', 21, 30, N'313401,313402,313403,313404,313405,313406,313307,313308,313309,313310,313311,313312', N'313401,313402,313403,313404,313405,313406,313307,313308,313309,313310,313311,313312', N'313407,313408,313409,313410,313411,313412,313401,313402,313403,313404,313405,313406,313307,313308,313309,313310,313311,313312', N'313407,313408,313409,313410,313411,313412,313401,313402,313403,313404,313405,313406,313307,313308,313309,313310,313311,313312', N'', N'', N'', N'Tương truyền trăm năm trước trang viên của một quý tộc bị một trận ôn dịch lấy đi sinh mạng của hàng trăm người. Nhà thám hiểm Toni vì muốn nghiên cứu lịch sử văn hóa đã mạo hiểm đi vào, không ngờ bị một người bí ẩn bắt đi, Toni phát tín hiệu cầu cứu, người chơi nhận được tín hiệu hãy mau đến cứu Toni!', 10, N'30-44|45-54|55-64|65-70', N'', 30, 70, N'1000K|2000K|3000K|8000K|0|0', N'');
